parameters.jsCode:
const selectedDay = $('Data Normalizer').item.json.value;
const userId = $('Data Normalizer').item.json.user_id;

const days = {
  sat: "Saturday",
  sun: "Sunday",
  mon: "Monday",
  tue: "Tuesday",
  wed: "Wednesday",
  thu: "Thursday",
  fri: "Friday"
};

if (!days[selectedDay]) {
  return [{
    json: {
      user_id: userId,
      selected_day: null,
      error: "invalid_day",
      received_value: selectedDay
    }
  }];
}

return [{
  json: {
    user_id: userId,
    selected_day: days[selectedDay]
  }
}];

const userId =
  $json.callback_query?.from?.id?.toString() ||
  $json.message?.from?.id?.toString();

if (!userId) return [];

const isCallback = !!$json.callback_query;
const value = isCallback
  ? ($json.callback_query.data || '')
  : ($json.message?.text || '').trim();

return [{
  json: {
    user_id: userId,
    chat_id: ($json.callback_query?.message?.chat?.id ?? $json.message?.chat?.id ?? userId).toString(),
    message_type: isCallback ? 'callback_query' : 'text',
    value,
    text: isCallback ? '' : ($json.message?.text || '').trim(),
    callback_query_id: $json.callback_query?.id || null
  }
}];

const selectedDay = $('Process Selected Day').item.json.selected_day;
const userId = $('Process Selected Day').item.json.user_id;

// Find the selected day in Schedule
const schedule = $input.all().find(item => {
  return item.json.Day === selectedDay;
});

if (!schedule) {
  return [{
    json: {
      user_id: userId,
      selected_day: selectedDay,
      available: false,
      reason: "day_not_found"
    }
  }];
}

const data = schedule.json;

// Check if the clinic works on this day
const active = String(data.Active).toLowerCase() === "true";

if (!active) {
  return [{
    json: {
      user_id: userId,
      selected_day: selectedDay,
      available: false,
      reason: "day_closed"
    }
  }];
}

return [{
  json: {
    user_id: userId,
    selected_day: selectedDay,
    available: true,
    start_time: data["Start Time"],
    end_time: data["End Time"],
    max_patients: Number(data["Max Patients"])
  }
}];

const selectedDay = $json.selected_day;
const userId = $json.user_id;

const dayNumbers = {Sunday:7, Monday:1, Tuesday:2, Wednesday:3, Thursday:4, Friday:5, Saturday:6};
const targetDay = dayNumbers[selectedDay];
if (!targetDay) return [{json:{...$json,error:"invalid_day"}}];

const now = new Date(new Date().toLocaleString("en-US",{timeZone:"Africa/Cairo"}));
const currentDay = now.getDay() === 0 ? 7 : now.getDay();
let daysUntil = targetDay - currentDay;
if (daysUntil < 0) daysUntil += 7;

// If today was selected but clinic hours are already over, use next week.
if (daysUntil === 0 && $json.end_time) {
  const [h,m] = String($json.end_time).split(':').map(Number);
  if (Number.isFinite(h) && Number.isFinite(m) &&
      (now.getHours() > h || (now.getHours() === h && now.getMinutes() >= m))) {
    daysUntil = 7;
  }
}

const bookingDate = new Date(now);
bookingDate.setDate(now.getDate() + daysUntil);

const date = `${bookingDate.getFullYear()}-${String(bookingDate.getMonth()+1).padStart(2,"0")}-${String(bookingDate.getDate()).padStart(2,"0")}`;
return [{json:{...$json,booking_date:date}}];

const bookings = $('Get Bookings').all();
const bookingData = $('Get Session Final').item.json;

const bookingDate = String(bookingData['Selected Date'] || '');
const userId = String(bookingData['User ID'] || '');

function real(item) {
  return item?.json && Object.values(item.json).some(
    v => v !== null && v !== undefined && v !== ''
  );
}

const realBookings = bookings.filter(real);

const duplicate = realBookings.find(b =>
  String(b.json['User ID'] || '') === userId &&
  String(b.json.Date || '') === bookingDate &&
  String(b.json.Status || '').toLowerCase() !== 'cancelled'
);

const queueNumber = realBookings.length + 1;
const maxPatients = Number($input.first().json['Max Patients'] || 0);

return [{
  json: {
    user_id: userId,
    booking_date: bookingDate,
    name: bookingData.Name,
    phone: bookingData.Phone,
    service: bookingData.Service,
    day: bookingData.Day,
    queue_number: queueNumber,
    max_patients: maxPatients,
    bookings_count: realBookings.length,

    // TRUE = this user already has a booking on this date
    duplicate: !!duplicate,

    // Availability is false if duplicate OR clinic is full
    available: !duplicate && queueNumber <= maxPatients,

    duplicate_booking: duplicate?.json || null
  }
}];

