const selectedService = $('Data Normalizer').item.json.value;
const userId = $('Data Normalizer').item.json.user_id;

const services = {
  check: "كشف",
  clean: "تنظيف جير",
  gum: "توريد لثة",
  ortho: "تقويم",
  extract: "خلع",
  filling: "حشو عادي",
  root: "حشو عصب",
  laser_white: "تبييض بالليزر"
};

if (!services[selectedService]) {
  return [{
    json: {
      user_id: userId,
      selected_service: null,
      error: "invalid_service",
      received_value: selectedService
    }
  }];
}

return [{
  json: {
    user_id: userId,
    selected_service: services[selectedService]
  }
}];

const name = $('Data Normalizer').item.json.text;
const userId = $('Data Normalizer').item.json.user_id;

return [{
  json: {
    user_id: userId,
    name: name.trim()
  }
}];

const raw = String($('Data Normalizer').item.json.text || '').trim();
const userId = $('Data Normalizer').item.json.user_id;
let phone = raw.replace(/[^\d+]/g,'');

if (phone.startsWith('+20')) phone = '0' + phone.slice(3);
if (phone.startsWith('20') && phone.length === 12) phone = '0' + phone.slice(2);

if (!/^01[0125]\d{8}$/.test(phone)) {
  return [{json:{user_id:userId,phone:null,error:"invalid_phone"}}];
}

return [{json:{user_id:userId,phone}}];

